CREATE TABLE organizations (id UUID PRIMARY KEY, name VARCHAR(100) NOT NULL, approved BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE accounts (id UUID PRIMARY KEY, username VARCHAR(32) NOT NULL UNIQUE, display_name VARCHAR(40) NOT NULL,
 password_hash VARCHAR(256) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('PLAYER','INSTITUTION')),
 organization_id UUID REFERENCES organizations(id), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CHECK ((role='PLAYER' AND organization_id IS NULL) OR (role='INSTITUTION' AND organization_id IS NOT NULL)));
CREATE TABLE rate_limits (bucket_key VARCHAR(128) PRIMARY KEY, hits INT NOT NULL, reset_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE strategies (id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES accounts(id), title VARCHAR(80) NOT NULL,
 created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE strategy_versions (id UUID PRIMARY KEY, strategy_id UUID NOT NULL REFERENCES strategies(id), revision INT NOT NULL,
 model_hash VARCHAR(64) NOT NULL, input_hash VARCHAR(64) NOT NULL, placements TEXT NOT NULL, events TEXT NOT NULL,
 design_note VARCHAR(2000) NOT NULL, cost NUMERIC(14,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL,
 UNIQUE(strategy_id,revision));
CREATE TABLE simulation_jobs (id UUID PRIMARY KEY, version_id UUID NOT NULL REFERENCES strategy_versions(id), owner_id UUID NOT NULL REFERENCES accounts(id),
 request_key UUID NOT NULL, state VARCHAR(20) NOT NULL CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','REJECTED')),
 model_hash VARCHAR(64) NOT NULL, input_hash VARCHAR(64) NOT NULL, result TEXT, error_code VARCHAR(80),
 lease_token UUID, lease_until TIMESTAMP WITH TIME ZONE, attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL,
 finished_at TIMESTAMP WITH TIME ZONE, UNIQUE(owner_id,request_key));
CREATE INDEX jobs_queue ON simulation_jobs(state,created_at);
CREATE TABLE submissions (id UUID PRIMARY KEY, job_id UUID NOT NULL UNIQUE REFERENCES simulation_jobs(id), owner_id UUID NOT NULL REFERENCES accounts(id),
 model_hash VARCHAR(64) NOT NULL, score NUMERIC(16,8) NOT NULL, cost NUMERIC(14,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE research_consents (owner_id UUID NOT NULL REFERENCES accounts(id), organization_id UUID NOT NULL REFERENCES organizations(id),
 granted BOOLEAN NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(owner_id,organization_id));
CREATE TABLE audit_events (id UUID PRIMARY KEY, actor_id UUID REFERENCES accounts(id), action VARCHAR(40) NOT NULL,
 object_id UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL PRIMARY KEY, SESSION_ID CHAR(36) NOT NULL,
 CREATION_TIME BIGINT NOT NULL, LAST_ACCESS_TIME BIGINT NOT NULL, MAX_INACTIVE_INTERVAL INT NOT NULL,
 EXPIRY_TIME BIGINT NOT NULL, PRINCIPAL_NAME VARCHAR(100));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES (SESSION_PRIMARY_ID CHAR(36) NOT NULL, ATTRIBUTE_NAME VARCHAR(200) NOT NULL,
 ATTRIBUTE_BYTES BYTEA NOT NULL, PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),
 FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
